# 万能加载 B 站视频（自动语音转文字，不怕没字幕）
def load_bilibili_video(url: str):
    # 1. 下载音频
    audio_file = "bilibili_audio"
    ydl_opts = {
        "format": "bestaudio/best",
        "postprocessors": [{
            "key": "FFmpegExtractAudio",
            "preferredcodec": "mp3",
        }],
        "outtmpl": audio_file,
        "noplaylist": True,  # 只下一集
        "quiet": False
    }

    # yt_dlp视频下载器
    # with yt_dlp.YoutubeDL(ydl_opts) as ydl:
    #     ydl.download([url])

    # 2. 语音转文字（支持中文）
    print("📦 正在加载 Whisper 模型（第一次需要下载约1.5GB，请耐心等待）...")
    # large medium small base tiny
    model = whisper.load_model("base")
    # model = whisper.load_model("medium")
    print("✅ 模型加载完成！")

    print("🎙️ 开始语音识别...")
    result = model.transcribe(r"D:\work_space\python\langChain-demo\main\data\下载.mp4", language="zh", fp16=False)
    # result = model.transcribe("bilibili_audio.mp3", language="zh", fp16=False)
    print("✅ 语音识别完成！")

    # 3. 生成 LangChain Document
    return Document(
        page_content=result["text"],
        metadata={"source": url, "type": "bilibili"}
    )


